/**
 * Bucket playbooks ("skills"): how to manage a bucket. Derived ONCE per bucket — from history when
 * there is enough of it, otherwise from the best available assumption — then FIXED. A fixed playbook
 * is never regenerated by a sync; only the user can regenerate (new version) or edit it.
 */
import type { Store } from "../../store/store.js";
import { BucketSkill, PlaybookStep as PlaybookStepSchema, type Theme, type ActionItem, type Decision, type Escalation, type Risk, type Signal, type BusinessMetric, type Evidence, type EvidenceRef } from "../../domain/index.js";
import type { z } from "zod";
type PlaybookStep = z.infer<typeof PlaybookStepSchema>;
import type { IntelligenceBackend } from "../backends/types.js";
import { generateBucketSkill, type SkillContext, type BucketSkillInput } from "../skills/index.js";
import type { Logger } from "../../logging/logger.js";
import { newId, nowIso, uniq, daysAgo } from "../../util.js";

const MIN_HISTORY_EVIDENCE = 4;
const MIN_HISTORY_OBJECTS = 2;

export interface BucketHistory {
  theme: Theme; evidence: Evidence[]; actions: ActionItem[]; decisions: Decision[]; escalations: Escalation[]; risks: Risk[]; signals: Signal[]; metrics: BusinessMetric[];
  people: Array<{ name: string; count: number }>; forums: string[]; sourceTypes: string[]; days: number;
}

export function collectBucketHistory(store: Store, theme: Theme, userName: string): BucketHistory {
  const evidence = store.getEvidenceMany(theme.evidence.map((e) => e.evidence_id));
  const objectsEvidence = new Set<string>();
  const actions = store.listObjects<ActionItem>({ type: "action", theme_id: theme.id, includeHidden: false });
  const decisions = store.listObjects<Decision>({ type: "decision", theme_id: theme.id });
  const escalations = store.listObjects<Escalation>({ type: "escalation", theme_id: theme.id });
  const risks = store.listObjects<Risk>({ type: "risk", theme_id: theme.id });
  const signals = store.listObjects<Signal>({ type: "signal", theme_id: theme.id });
  const metrics = store.listObjects<BusinessMetric>({ type: "metric", theme_id: theme.id });
  for (const o of [...actions, ...decisions, ...escalations, ...risks, ...signals]) for (const r of o.evidence) objectsEvidence.add(r.evidence_id);
  const all = [...evidence, ...store.getEvidenceMany([...objectsEvidence].filter((id) => !evidence.some((e) => e.evidence_id === id)))];
  const counts = new Map<string, number>();
  for (const e of all) for (const p of e.participants) { if (userName && p.name.toLowerCase() === userName.toLowerCase()) continue; counts.set(p.name, (counts.get(p.name) ?? 0) + 1); }
  const people = [...counts.entries()].map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count);
  const forums = uniq(all.filter((e) => e.source_type === "meeting" || e.source_type === "calendar_event").map((e) => e.title.replace(/\s*[—-]\s*notes?$/i, "").trim()));
  const dates = all.map((e) => e.occurred_at).sort();
  const days = dates.length >= 2 ? Math.max(1, Math.round((Date.parse(dates[dates.length - 1]!) - Date.parse(dates[0]!)) / 86_400_000)) : 0;
  return { theme, evidence: all, actions, decisions, escalations, risks, signals, metrics, people, forums, sourceTypes: uniq(all.map((e) => e.source_type)), days };
}

/** Deterministic derivation used by the mock backend and as the fallback when the model is unavailable. */
export function derivePlaybook(h: BucketHistory, ctx: SkillContext): BucketSkill {
  const enough = h.evidence.length >= MIN_HISTORY_EVIDENCE && (h.actions.length + h.decisions.length + h.escalations.length + h.risks.length) >= MIN_HISTORY_OBJECTS;
  const basis: BucketSkill["basis"] = enough ? "history" : h.evidence.length > 0 ? "mixed" : "assumption";
  const B = (hist: boolean): "history" | "assumption" => (hist ? "history" : "assumption");
  const primary = h.people[0]?.name ?? (h.actions.find((a) => a.owner)?.owner);
  const stakeholders = h.people.slice(1, 5).map((p) => p.name);
  const forums = h.forums.length ? h.forums.slice(0, 4) : ctx.terminology.MOR ? ["Monthly operations review"] : [];
  const review: BucketSkill["cadence"]["review"] = h.forums.some((f) => /daily|stand-?up/i.test(f)) ? "daily" : h.forums.some((f) => /weekly|1:1|huddle/i.test(f)) ? "weekly" : h.forums.some((f) => /monthly|MOR/i.test(f)) ? "monthly" : h.forums.some((f) => /quarter|QBR/i.test(f)) ? "quarterly" : "weekly";
  const signals = [
    ...h.metrics.map((m) => ({ name: m.name, source_types: ["metric"], threshold: m.delta !== undefined ? `move of ±${Math.max(5, Math.round(Math.abs(m.delta) * 100))}% vs 4-week baseline` : undefined, rationale: `Tracked in this bucket (${m.value}${m.unit ?? ""} as of ${m.as_of.slice(0, 10)}).` })),
    ...(h.actions.length ? [{ name: "Commitments without a firm date or past due", source_types: h.sourceTypes, threshold: "any commitment > 7 days overdue", rationale: `${h.actions.length} commitment(s) tracked; ${h.actions.filter((a) => a.due_at && a.due_at < nowIso() && !["completed", "dismissed"].includes(a.status)).length} overdue.` }] : []),
    ...(h.signals.filter((s) => s.evidence.length >= 2).slice(0, 2).map((s) => ({ name: s.statement, source_types: uniq(s.evidence.map((r) => h.evidence.find((e) => e.evidence_id === r.evidence_id)?.source_type as string | undefined).filter((x): x is string => !!x)), threshold: "raised again by a second team", rationale: `Repeated ${s.evidence.length} times in the evidence.` }))),
    ...(!h.metrics.length && !h.actions.length ? [{ name: `New mentions of ${h.theme.name}`, source_types: h.sourceTypes.length ? h.sourceTypes : ["email", "teams_message"], threshold: "≥ 3 mentions in a week", rationale: "No history yet: watch for the topic gaining momentum." }] : []),
  ];
  const steps: PlaybookStep[] = [
    { n: 1, stage: "sense", title: `Collect ${h.theme.name.toLowerCase()} signals`, description: h.sourceTypes.length ? `Signals for this bucket have come from ${h.sourceTypes.map((s) => s.replace("_", " ")).join(", ")}.` : "Watch email, Teams, meetings and metrics for this topic.", trigger: `Every sync; review ${review}`, owner: ctx.user.display_name || undefined, output: "New evidence linked to the bucket", basis: B(h.sourceTypes.length > 0) },
    { n: 2, stage: "interpret", title: "Separate facts, commitments and inferences", description: h.signals.length ? `Recurring signals: ${h.signals.slice(0, 2).map((s) => s.statement).join("; ")}.` : "Identify what changed, what conflicts, and where evidence is missing.", trigger: "New evidence in the bucket", output: "Updated state: what changed / current state", basis: B(h.signals.length > 0) },
    { n: 3, stage: "decide", title: h.decisions.length ? `Decisions in this bucket are made by ${uniq(h.decisions.map((d) => d.decision_maker).filter(Boolean)).join(", ") || "leadership"}` : "Frame the decision and who owns it", description: h.decisions.length ? `${h.decisions.filter((d) => d.status === "recorded").length} recorded, ${h.decisions.filter((d) => d.status !== "recorded").length} open.` : "No decisions recorded yet; agree the decision rights at the next review.", trigger: h.decisions.some((d) => d.needed_by) ? "A decision deadline approaches" : "A tradeoff or approval surfaces", owner: uniq(h.decisions.map((d) => d.decision_maker).filter(Boolean))[0] ?? ctx.important_roles[0]?.name ?? ctx.important_roles[0]?.title, output: "Recorded decision with rationale", basis: B(h.decisions.length > 0) },
    { n: 4, stage: "align", title: forums.length ? `Align in ${forums[0]}` : "Align owners in the standing forum", description: forums.length ? `Forums seen in history: ${forums.join(", ")}.` : "Use the operating cadence to communicate decisions and asks.", trigger: `${review} review`, owner: primary, output: "Owners know the decision, rationale and ask", basis: B(forums.length > 0) },
    { n: 5, stage: "execute", title: "Track commitments to closure", description: h.actions.length ? `${h.actions.filter((a) => a.status === "completed").length} of ${h.actions.length} tracked commitments completed; escalate when overdue.` : "Log commitments with owner and date; chase at the review.", trigger: "Commitment recorded or overdue", owner: primary, output: "Closed actions, lessons captured in the journal", basis: B(h.actions.length > 0) },
  ];
  const escalationTargets = uniq(h.escalations.map((e) => e.target_decision_maker).filter((x): x is string => !!x));
  const escalation_path = [
    { condition: "Commitment > 14 days overdue or blocked outside the team", to: escalationTargets[0] ?? (ctx.important_roles.find((r) => /vp|vice|director|head/i.test(r.title))?.name || ctx.important_roles[0]?.title || "your manager"), within_days: 3 },
    ...(h.escalations.length ? [{ condition: `Pattern seen before: ${h.escalations[0]!.issue}`, to: escalationTargets[0] ?? "leadership", within_days: 2 }] : []),
  ];
  const decision_rights = uniq(h.decisions.map((d) => `${d.topic}|${d.decision_maker ?? "unassigned"}`)).slice(0, 5).map((s) => { const [decision, maker] = s.split("|"); return { decision: decision!, maker: maker! }; });
  const recurring_blockers = uniq([...h.signals.filter((s) => s.evidence.length >= 2).map((s) => s.statement), ...h.risks.filter((r) => r.status !== "closed").map((r) => r.title)]).slice(0, 5);
  const evidence: EvidenceRef[] = h.evidence.slice(0, 12).map((e) => ({ evidence_id: e.evidence_id, role: "supports" as const }));
  const rationale = basis === "history"
    ? `Derived from ${h.evidence.length} evidence items over ${h.days} day(s), ${h.actions.length} commitment(s), ${h.decisions.length} decision(s), ${h.escalations.length} escalation(s) and ${h.people.length} people involved.`
    : basis === "mixed" ? `Only ${h.evidence.length} evidence item(s) so far; cadence and owners are inferred from them, the rest is the standard operating loop. Regenerate once more history exists.`
    : `No history for this bucket yet; this is the standard executive operating loop as a starting assumption. Edit it or regenerate after a few syncs.`;
  return BucketSkill.parse({
    id: newId("skl"), theme_id: h.theme.id, version: 1, status: "fixed", generated_at: nowIso(), fixed_at: nowIso(), generated_by: "rules", basis,
    history_depth: { evidence: h.evidence.length, objects: h.actions.length + h.decisions.length + h.escalations.length + h.risks.length, days: h.days },
    purpose: h.theme.description ? `Keep "${h.theme.name}" under control: ${h.theme.description}` : `Keep "${h.theme.name}" visible, decided and executed.`,
    cadence: { review, forums, rationale: forums.length ? `Forums observed in the evidence.` : "No forum observed; default cadence assumed." },
    owners: { primary, stakeholders, rationale: primary ? `${primary} appears most often in this bucket's evidence.` : "No recurring owner observed yet." },
    signals_to_watch: signals.slice(0, 5), steps, escalation_path, decision_rights, recurring_blockers, evidence,
    confidence: basis === "history" ? 0.7 : basis === "mixed" ? 0.5 : 0.35, epistemic: "inference", rationale,
  });
}

export function historyToSkillInput(h: BucketHistory): BucketSkillInput {
  return {
    theme: { id: h.theme.id, name: h.theme.name, description: h.theme.description, pinned: h.theme.pinned },
    evidence: h.evidence.slice(0, 40).map((e) => ({ evidence_id: e.evidence_id, source_type: e.source_type, occurred_at: e.occurred_at, title: e.title, participants: e.participants.map((p) => p.name), text: e.text?.slice(0, 600) })),
    actions: h.actions.map((a) => ({ title: a.title, status: a.status, owner: a.owner, due_at: a.due_at })),
    decisions: h.decisions.map((d) => ({ topic: d.topic, status: d.status, decision_maker: d.decision_maker })),
    escalations: h.escalations.map((e) => ({ issue: e.issue, status: e.status, target: e.target_decision_maker })),
    risks: h.risks.map((r) => ({ title: r.title, status: r.status })),
    signals: h.signals.map((s) => ({ statement: s.statement, mentions: s.evidence.length })),
    metrics: h.metrics.map((m) => ({ name: m.name, value: m.value, unit: m.unit, delta: m.delta })),
    people: h.people.slice(0, 8), forums: h.forums, days: h.days,
  };
}

/** Generate playbooks for buckets that do not have one yet. Existing (fixed) playbooks are left untouched. */
export async function ensureBucketSkills(store: Store, backend: IntelligenceBackend, ctx: SkillContext, logger: Logger): Promise<{ generated: number; refresh_candidates: string[] }> {
  let generated = 0; const refresh_candidates: string[] = [];
  for (const theme of store.listThemes(false)) {
    const existing = store.currentBucketSkill(theme.id);
    const history = collectBucketHistory(store, theme, ctx.user.display_name);
    if (existing) {
      const enoughNow = history.evidence.length >= MIN_HISTORY_EVIDENCE && (history.actions.length + history.decisions.length + history.escalations.length + history.risks.length) >= MIN_HISTORY_OBJECTS;
      if (existing.basis !== "history" && enoughNow && !existing.user_adjusted) refresh_candidates.push(theme.id);
      continue;
    }
    let skill: BucketSkill;
    try {
      const out = await backend.runSkill(generateBucketSkill, historyToSkillInput(history), ctx, { logger });
      skill = BucketSkill.parse({ ...out, id: newId("skl"), theme_id: theme.id, version: 1, status: "fixed", generated_at: nowIso(), fixed_at: nowIso(), generated_by: backend.name === "mock" ? "rules" : "model", history_depth: { evidence: history.evidence.length, objects: history.actions.length + history.decisions.length + history.escalations.length + history.risks.length, days: history.days }, evidence: history.evidence.slice(0, 12).map((e) => ({ evidence_id: e.evidence_id, role: "supports" as const })), epistemic: "inference" });
    } catch (e) {
      logger.warn("playbook generation via backend failed; using rule derivation", { theme: theme.id, error: e });
      skill = derivePlaybook(history, ctx);
    }
    store.saveBucketSkill(skill);
    store.journal({ object_type: "bucket_skill", object_id: skill.id, event: "detected", actor: "system", summary: `Playbook v1 generated for "${theme.name}" (${skill.basis}) and fixed`, evidence: skill.evidence });
    generated++;
  }
  return { generated, refresh_candidates };
}

export function regenerateBucketSkill(store: Store, themeId: string, ctx: SkillContext, reason: string): BucketSkill {
  const theme = store.getTheme(themeId);
  if (!theme) throw new Error("bucket not found");
  const prev = store.currentBucketSkill(themeId);
  const skill = derivePlaybook(collectBucketHistory(store, theme, ctx.user.display_name), ctx);
  skill.version = (prev?.version ?? 0) + 1; skill.generated_by = "rules";
  if (prev?.user_notes) skill.user_notes = prev.user_notes;
  store.saveBucketSkill(skill);
  store.journal({ object_type: "bucket_skill", object_id: skill.id, event: "updated", actor: "user", summary: `Playbook regenerated to v${skill.version} (${skill.basis}): ${reason}`, before: { version: prev?.version }, after: { version: skill.version } });
  store.saveFeedback({ object_type: "theme", object_id: themeId, kind: "playbook_regenerate", payload: { reason, version: skill.version } });
  return skill;
}

export function editBucketSkill(store: Store, themeId: string, patch: Partial<BucketSkill>): BucketSkill {
  const cur = store.currentBucketSkill(themeId);
  if (!cur) throw new Error("no playbook for bucket");
  const allowed: Array<keyof BucketSkill> = ["purpose", "cadence", "owners", "signals_to_watch", "steps", "escalation_path", "decision_rights", "recurring_blockers", "user_notes", "status"];
  const before: Record<string, unknown> = {}; const after: Record<string, unknown> = {};
  for (const k of allowed) if (patch[k] !== undefined) { before[k] = cur[k]; (cur as Record<string, unknown>)[k] = patch[k]; after[k] = patch[k]; }
  cur.user_adjusted = true; cur.generated_by = "user"; if (cur.status === "fixed") cur.fixed_at = cur.fixed_at ?? nowIso();
  const parsed = BucketSkill.parse(cur);
  store.saveBucketSkill(parsed);
  store.journal({ object_type: "bucket_skill", object_id: parsed.id, event: "feedback", actor: "user", summary: `Playbook adjusted: ${Object.keys(after).join(", ")}`, before, after });
  store.saveFeedback({ object_type: "theme", object_id: themeId, kind: "playbook_edit", payload: { fields: Object.keys(after) } });
  return parsed;
}

export const PLAYBOOK_MIN = { evidence: MIN_HISTORY_EVIDENCE, objects: MIN_HISTORY_OBJECTS };
export type { Theme };
void daysAgo;
